 * File and Documentation generated by Gemini
 * File Name: EntrantListScreen.kt
 * Purpose: Allows campsite owners to view the list of entrants who have joined a specific lottery pool.
 * Architectural Role: View layer for owner waitlist inspection.
 * Outstanding Issues: None.
 */
package com.example.campsitelottery

import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.RectangleShape
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import androidx.navigation.NavController
import com.google.firebase.firestore.FirebaseFirestore

@Composable
fun EntrantListScreen(
    navController: NavController,
    waitlistId: String
) {
    var waitlist by remember { mutableStateOf<Waitlist?>(null) }
    var entrantNames by remember { mutableStateOf<List<String>>(emptyList()) }
    var isLoading by remember { mutableStateOf(true) }

    // Fetch the waitlist and resolve entrant names from their Device/User IDs
    LaunchedEffect(waitlistId) {
        val db = FirebaseFirestore.getInstance()
        db.collection("waitlists").document(waitlistId).get()
            .addOnSuccessListener { doc ->
                val fetchedWaitlist = doc.toObject(Waitlist::class.java)
                waitlist = fetchedWaitlist

                if (fetchedWaitlist != null && fetchedWaitlist.joinedEntrantIds.isNotEmpty()) {
                    // Fetch user profiles for all joined entrant IDs
                    db.collection("users")
                        .whereIn(com.google.firebase.firestore.FieldPath.documentId(), fetchedWaitlist.joinedEntrantIds)
                        .get()
                        .addOnSuccessListener { userSnapshot ->
                            val names = userSnapshot.documents.mapNotNull { it.getString("name") }
                            entrantNames = names.ifEmpty { fetchedWaitlist.joinedEntrantIds } // Fallback to IDs if names aren't set
                            isLoading = false
                        }
                        .addOnFailureListener {
                            entrantNames = fetchedWaitlist.joinedEntrantIds // Fallback on error
                            isLoading = false
                        }
                } else {
                    isLoading = false
                }
            }
            .addOnFailureListener {
                isLoading = false
            }
    }

    Column(modifier = Modifier.fillMaxSize().padding(16.dp)) {
        Button(onClick = { navController.popBackStack() }, shape = RectangleShape) {
            Text("Back")
        }

        Spacer(modifier = Modifier.height(16.dp))
        Text(text = "Joined Entrants", fontSize = 28.sp)
        Spacer(modifier = Modifier.height(16.dp))

        when {
            isLoading -> {
                Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                    CircularProgressIndicator()
                }
            }
            waitlist == null || waitlist!!.joinedEntrantIds.isEmpty() -> {
                Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                    Text("No entrants have joined this lottery yet.", fontSize = 16.sp)
                }
            }
            else -> {
                LazyColumn(modifier = Modifier.fillMaxWidth().weight(1f)) {
                    items(entrantNames) { entrant ->
                        Card(
                            modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp)
                        ) {
                            Column(modifier = Modifier.padding(16.dp)) {
                                Text(text = "Entrant: $entrant", fontSize = 18.sp)
                            }
                        }
                    }
                }
            }
        }
    }
}